                <button 
                    onClick={generateOperationalManual} 
                    className="text-[10px] text-text-secondary hover:text-white flex items-center justify-center gap-1.5 mx-auto transition-colors font-mono"
                >
                    <DownloadIcon className="w-3 h-3" />
